import os
import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_FILE = '/app/workspace/stat_ocr.xlsx'

# Priority groups (highest to lowest)
PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
]

EXCLUSION = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

# Pattern for monetary number (with optional commas and decimals)
NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})*(?:\.\d{1,2})|\d+\.\d{1,2}|\d+)')


def extract_amount_from_line_pair(line, next_line):
    """Try to extract a numeric amount from line, fall back to last number on next_line."""
    nums = NUM_RE.findall(line)
    # Prefer numbers with decimal
    decimal_nums = [n for n in nums if '.' in n]
    if decimal_nums:
        return decimal_nums[-1]
    if nums:
        # Could be okay but typically receipt totals have decimals
        return nums[-1]
    if next_line:
        nums2 = NUM_RE.findall(next_line)
        decimal_nums2 = [n for n in nums2 if '.' in n]
        if decimal_nums2:
            return decimal_nums2[-1]
        if nums2:
            return nums2[-1]
    return None


def normalize_amount(num_str):
    if num_str is None:
        return None
    n = num_str.replace(',', '')
    try:
        f = float(n)
    except ValueError:
        return None
    return f"{f:.2f}"


def find_total_amount(text):
    lines = [l.strip() for l in text.splitlines()]
    upper_lines = [l.upper() for l in lines]

    for group in PRIORITY_KEYWORDS:
        candidates = []
        for i, line_upper in enumerate(upper_lines):
            if not line_upper:
                continue
            # Check if any keyword in group matches
            kw_match = None
            for kw in group:
                if kw in line_upper:
                    kw_match = kw
                    break
            if kw_match is None:
                continue
            # Check exclusions on the same line
            excluded = False
            for ex in EXCLUSION:
                # If keyword is "TOTAL" we need to exclude SUBTOTAL/SUB TOTAL/NETT etc.
                # But carefully: the line may contain "TOTAL" and also "SUBTOTAL"
                if ex in line_upper:
                    # Special case: TAX/GST/SST/CHANGE - these mean we should skip
                    # However, "Total Inclusive GST" contains GST but is a valid total
                    # We need to be careful here
                    if kw_match == 'TOTAL' and ex in ('TAX', 'GST', 'SST'):
                        # only exclude if line is dominated by tax/gst/sst (e.g. "GST 6%", "TAX AMT")
                        # If line has "TOTAL" prominently and amount, accept
                        # But excluded if it's specifically a "tax total" line
                        if 'TOTAL' in line_upper and re.search(r'TOTAL\b', line_upper):
                            # accept unless specifically about tax
                            # heuristic: if line starts with TAX/GST/SST then skip
                            stripped = line_upper.strip()
                            if stripped.startswith(ex):
                                excluded = True
                                break
                            else:
                                continue
                    excluded = True
                    break
            if excluded:
                continue
            # For TOTAL keyword, also exclude lines that are SUBTOTAL/SUB TOTAL
            if kw_match == 'TOTAL':
                if 'SUBTOTAL' in line_upper or 'SUB TOTAL' in line_upper or 'SUB-TOTAL' in line_upper:
                    continue
            candidates.append(i)

        # Process candidates - find amount
        # Prefer candidates that have an amount on the same line, else fallback to next line
        for idx in candidates:
            line = lines[idx]
            next_line = lines[idx + 1] if idx + 1 < len(lines) else ''
            # Remove the keyword first to focus on amounts after
            amount = extract_amount_from_line_pair(line, next_line)
            if amount:
                normalized = normalize_amount(amount)
                if normalized is not None:
                    return normalized

    return None


# Date patterns
DATE_PATTERNS = [
    # DD/MM/YYYY or DD-MM-YYYY
    (re.compile(r'\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b'), 'dmy'),
    # DD/MM/YY
    (re.compile(r'\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b'), 'dmy2'),
    # YYYY/MM/DD
    (re.compile(r'\b(\d{4})[/\-](\d{1,2})[/\-](\d{1,2})\b'), 'ymd'),
]


def find_date(text):
    for pattern, kind in DATE_PATTERNS:
        for m in pattern.finditer(text):
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + y if y < 50 else 1900 + y
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if 1 <= d <= 31 and 1 <= mo <= 12 and 1900 <= y <= 2100:
                    return f"{y:04d}-{mo:02d}-{d:02d}"
            except ValueError:
                continue
    return None


def process_image(path):
    img = Image.open(path)
    text = pytesseract.image_to_string(img)
    date = find_date(text)
    amount = find_total_amount(text)
    return date, amount, text


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        try:
            date, amount, text = process_image(path)
        except Exception as e:
            print(f"Error processing {fname}: {e}")
            date, amount = None, None
        print(f"{fname}: date={date}, amount={amount}")
        ws.append([fname, date, amount])
    wb.save(OUT_FILE)
    print(f"Saved to {OUT_FILE}")


if __name__ == '__main__':
    main()

