import os
import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_FILE = '/app/workspace/stat_ocr.xlsx'

# Priority groups (highest to lowest)
PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['NETT TOTAL', 'NET TOTAL', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'TOTAL', 'AMOUNT'],
]

EXCLUSION = ['SUBTOTAL', 'SUB TOTAL', 'SUB-TOTAL', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']
TAX_EXCLUSION = ['TAX', 'GST', 'SST']

NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{1,2}|\d+)')
# Fuzzy number with possible OCR errors in decimal portion (e.g. 15.u00 → 15.00)
FUZZY_NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})+\.[\dduUoOiIlLg]{1,3}|\d+\.[\dduUoOiIlLg]{1,3})')

OCR_DIGIT_MAP = str.maketrans({
    'o': '0', 'O': '0', 'D': '0', 'u': '0', 'U': '0', 'g': '9', 'G': '0',
    'i': '1', 'I': '1', 'l': '1', 'L': '1',
    'S': '5', 's': '5', 'B': '8', 'Z': '2', 'q': '9',
})


def extract_amount_from_line(line):
    """Extract a monetary amount from a line. Prefer values with two decimals."""
    # First try clean numbers
    nums = NUM_RE.findall(line)
    decimal_two = [n for n in nums if re.match(r'^[\d,]+\.\d{2}$', n)]
    if decimal_two:
        return decimal_two[-1]
    # Fuzzy match for OCR errors
    fuzzy_nums = FUZZY_NUM_RE.findall(line)
    fixed = []
    for n in fuzzy_nums:
        if '.' in n:
            int_part, dec_part = n.rsplit('.', 1)
            dec_part_fixed = dec_part.translate(OCR_DIGIT_MAP)
            if re.match(r'^\d{1,3}$', dec_part_fixed):
                # Take first 2 digits as decimal
                if len(dec_part_fixed) >= 2:
                    dec_part_fixed = dec_part_fixed[:2]
                else:
                    dec_part_fixed = dec_part_fixed + '0'
                fixed.append(f"{int_part}.{dec_part_fixed}")
    if fixed:
        return fixed[-1]
    if nums:
        return nums[-1]
    return None


def normalize_amount(num_str):
    if num_str is None:
        return None
    n = num_str.replace(',', '')
    try:
        f = float(n)
    except ValueError:
        return None
    return f"{f:.2f}"


def line_passes_tax_check(line_upper, kw_match):
    """For lines containing TAX/GST/SST, accept if also has INCL/INCLUSIVE/INCLUDING.
    Exclude if line is essentially a 'Total GST'/'Total TAX'/'Total SST' line."""
    has_tax_word = any(t in line_upper for t in TAX_EXCLUSION)
    if not has_tax_word:
        return True
    # If line has INCL/INCLUSIVE/INCLUDING, it's likely "Total Incl GST" - accept
    if re.search(r'\bINCL', line_upper) or 'INCLUSIVE' in line_upper or 'INCLUDING' in line_upper:
        return True
    # Otherwise it's likely a tax breakdown like "Total GST (RM)" - exclude
    return False


def find_total_amount(text):
    lines = [l.strip() for l in text.splitlines()]
    upper_lines = [l.upper() for l in lines]

    for group_idx, group in enumerate(PRIORITY_KEYWORDS):
        candidates = []
        for i, line_upper in enumerate(upper_lines):
            if not line_upper:
                continue
            kw_match = None
            for kw in group:
                if kw in line_upper:
                    kw_match = kw
                    break
            if kw_match is None:
                continue
            # Standard exclusions
            if any(ex in line_upper for ex in EXCLUSION):
                continue
            # Tax exclusion (only for keywords that aren't already specifying RM)
            if not line_passes_tax_check(line_upper, kw_match):
                continue
            candidates.append((i, kw_match))

        if not candidates:
            continue

        # Try to extract amount from candidates
        # Prefer LAST candidate with extractable amount on same line
        for i, kw_match in reversed(candidates):
            line = lines[i]
            amount = extract_amount_from_line(line)
            if amount is not None:
                # Sanity: prefer decimal amounts
                if '.' in amount:
                    n = normalize_amount(amount)
                    if n is not None:
                        return n

        # Same line had no decimal amount — try fallback to next line
        for i, kw_match in reversed(candidates):
            next_line = lines[i + 1] if i + 1 < len(lines) else ''
            if next_line:
                amount = extract_amount_from_line(next_line)
                if amount is not None and '.' in amount:
                    n = normalize_amount(amount)
                    if n is not None:
                        return n

        # Last resort: any number from any candidate line
        for i, kw_match in reversed(candidates):
            line = lines[i]
            amount = extract_amount_from_line(line)
            if amount is not None:
                n = normalize_amount(amount)
                if n is not None:
                    return n

    return None


# Date patterns
DATE_PATTERNS = [
    # DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
    (re.compile(r'\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})\b'), 'dmy'),
    # DD/MM/YY
    (re.compile(r'\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})\b'), 'dmy2'),
    # YYYY/MM/DD
    (re.compile(r'\b(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})\b'), 'ymd'),
]


def find_date(text):
    candidates = []
    for pattern, kind in DATE_PATTERNS:
        for m in pattern.finditer(text):
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + y if y < 50 else 1900 + y
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2030:
                    candidates.append(f"{y:04d}-{mo:02d}-{d:02d}")
            except ValueError:
                continue
    if candidates:
        return candidates[0]
    return None


def ocr_with_preprocessing(path):
    img = Image.open(path)
    # Upscale for better OCR
    w, h = img.size
    if max(w, h) < 1500:
        img = img.resize((w * 2, h * 2), Image.LANCZOS)
    text = pytesseract.image_to_string(img)
    return text


def process_image(path):
    text = ocr_with_preprocessing(path)
    date = find_date(text)
    amount = find_total_amount(text)
    return date, amount, text


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        try:
            date, amount, text = process_image(path)
        except Exception as e:
            print(f"Error processing {fname}: {e}")
            date, amount = None, None
        print(f"{fname}: date={date}, amount={amount}")
        ws.append([fname, date, amount])
    wb.save(OUT_FILE)
    print(f"Saved to {OUT_FILE}")


if __name__ == '__main__':
    main()

