    img = Image.open(path)
    w, h = img.size
    if scale > 1:
        img = img.resize((w * scale, h * scale), Image.LANCZOS)
    config = ''
    if psm is not None:
        config = f'--psm {psm}'
    return pytesseract.image_to_string(img, config=config)


