import os
import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_FILE = '/app/workspace/stat_ocr.xlsx'

# Priority groups (highest to lowest)
PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM', 'TOTAL (RM)'],
    ['TOTAL AMOUNT'],
    ['NETT TOTAL', 'NET TOTAL', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'TOTAL', 'AMOUNT'],
]

EXCLUSION = ['SUBTOTAL', 'SUB TOTAL', 'SUB-TOTAL', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']
TAX_EXCLUSION = ['TAX', 'GST', 'SST']

NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{1,2}|\d+)')
FUZZY_NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})+\.[\dduUoOiIlLg]{1,3}|\d+\.[\dduUoOiIlLg]{1,3})')

OCR_DIGIT_MAP = str.maketrans({
    'o': '0', 'O': '0', 'D': '0', 'u': '0', 'U': '0', 'g': '9', 'G': '0',
    'i': '1', 'I': '1', 'l': '1', 'L': '1',
})


def normalize_line_for_keyword(s):
    """Normalize a line for keyword matching: replace common OCR substitutions."""
    s = s.upper()
    # 'RN' likely 'RM' (currency)
    s = re.sub(r'\bRN\b', 'RM', s)
    s = re.sub(r'\bRH\b', 'RM', s)
    return s


def extract_amount_from_line(line):
    nums = NUM_RE.findall(line)
    decimal_two = [n for n in nums if re.match(r'^[\d,]+\.\d{2}$', n)]
    if decimal_two:
        return decimal_two[-1]
    fuzzy_nums = FUZZY_NUM_RE.findall(line)
    fixed = []
    for n in fuzzy_nums:
        if '.' in n:
            int_part, dec_part = n.rsplit('.', 1)
            dec_part_fixed = dec_part.translate(OCR_DIGIT_MAP)
            if re.match(r'^\d{1,3}$', dec_part_fixed):
                if len(dec_part_fixed) >= 2:
                    dec_part_fixed = dec_part_fixed[:2]
                else:
                    dec_part_fixed = dec_part_fixed + '0'
                fixed.append(f"{int_part}.{dec_part_fixed}")
    if fixed:
        return fixed[-1]
    if nums:
        return nums[-1]
    return None


def normalize_amount(num_str):
    if num_str is None:
        return None
    n = num_str.replace(',', '')
    try:
        f = float(n)
    except ValueError:
        return None
    return f"{f:.2f}"


def line_passes_tax_check(line_upper):
    has_tax_word = any(t in line_upper for t in TAX_EXCLUSION)
    if not has_tax_word:
        return True
    if re.search(r'\bINCL', line_upper) or 'INCLUSIVE' in line_upper or 'INCLUDING' in line_upper:
        return True
    return False


def find_total_amount(text):
    raw_lines = [l.strip() for l in text.splitlines()]
    norm_lines = [normalize_line_for_keyword(l) for l in raw_lines]

    for group_idx, group in enumerate(PRIORITY_KEYWORDS):
        candidates = []
        for i, line_upper in enumerate(norm_lines):
            if not line_upper:
                continue
            kw_match = None
            for kw in group:
                if kw in line_upper:
                    kw_match = kw
                    break
            if kw_match is None:
                continue
            if any(ex in line_upper for ex in EXCLUSION):
                continue
            if not line_passes_tax_check(line_upper):
                continue
            # Skip "Total Gross" - that's a different concept (often gross of refund)
            if 'TOTAL GROSS' in line_upper:
                continue
            # Skip "Total Item(s)" / "Total Items"
            if re.search(r'TOTAL\s+ITEM', line_upper):
                continue
            # Skip Total quantity
            if re.search(r'TOTAL\s+QU?ANTITY', line_upper):
                continue
            # Skip Total Savings / total saving
            if 'TOTAL SAVING' in line_upper:
                continue
            # Skip "GST SUMMARY" context - line equal to "TOTAL: <amt>" alone
            # (this is the summary total; it's not the receipt total)
            candidates.append((i, kw_match))

        if not candidates:
            continue

        # For lowest-priority group (group 4), the LAST candidate is usually the
        # final total. For groups 1-3, it's usually unique anyway.
        # Try last candidates first for amount with two decimals
        for i, kw_match in reversed(candidates):
            line = raw_lines[i]
            amount = extract_amount_from_line(line)
            if amount is not None and '.' in amount:
                n = normalize_amount(amount)
                if n is not None:
                    return n

        # Fallback: next line
        for i, kw_match in reversed(candidates):
            next_line = raw_lines[i + 1] if i + 1 < len(raw_lines) else ''
            if next_line:
                amount = extract_amount_from_line(next_line)
                if amount is not None and '.' in amount:
                    n = normalize_amount(amount)
                    if n is not None:
                        return n

        # Last resort: any number from candidates
        for i, kw_match in reversed(candidates):
            line = raw_lines[i]
            amount = extract_amount_from_line(line)
            if amount is not None:
                n = normalize_amount(amount)
                if n is not None:
                    return n

    return None


DATE_PATTERNS = [
    (re.compile(r'\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})\b'), 'dmy'),
    (re.compile(r'\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})\b'), 'dmy2'),
    (re.compile(r'\b(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})\b'), 'ymd'),
]


def find_date(text):
    candidates = []
    for pattern, kind in DATE_PATTERNS:
        for m in pattern.finditer(text):
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    y = 2000 + y if y < 50 else 1900 + y
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2030:
                    candidates.append(f"{y:04d}-{mo:02d}-{d:02d}")
            except ValueError:
                continue
    if candidates:
        return candidates[0]
    return None


def ocr_image(path, scale=2, psm=None):
    img = Image.open(path)
    w, h = img.size
    if scale > 1:
        img = img.resize((w * scale, h * scale), Image.LANCZOS)
    config = ''
    if psm is not None:
        config = f'--psm {psm}'
    return pytesseract.image_to_string(img, config=config)


def process_image(path):
    # Try multiple OCR strategies and pick the best result
    ocr_results = []
    for scale, psm in [(3, 6), (2, None), (3, None), (2, 6)]:
        try:
            text = ocr_image(path, scale=scale, psm=psm)
            ocr_results.append((scale, psm, text))
        except Exception:
            pass

    best_date = None
    best_amount = None

    for scale, psm, text in ocr_results:
        d = find_date(text)
        a = find_total_amount(text)
        if best_date is None and d is not None:
            best_date = d
        if best_amount is None and a is not None:
            best_amount = a
        if best_date is not None and best_amount is not None:
            break
    return best_date, best_amount


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        try:
            date, amount = process_image(path)
        except Exception as e:
            print(f"Error processing {fname}: {e}")
            date, amount = None, None
        print(f"{fname}: date={date}, amount={amount}")
        ws.append([fname, date, amount])
    wb.save(OUT_FILE)
    print(f"Saved to {OUT_FILE}")


if __name__ == '__main__':
    main()
